=== FILE: tb/repro_data_byte.v ===
// Repro for bucket A (data_byte_fail): data bits must leave LSB first.
// Checks only the eight data bits, sampled at mid-bit; ignores parity and stop length.
`timescale 1ns / 1ps
module tb_uart_frame_tx;
    localparam integer CPB = 4;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    integer checks   = 0;
    integer failures = 0;
    reg     done     = 1'b0;
    reg [8*64-1:0] nonce;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    task send_and_check;
        input [7:0] d;
        integer k;
        begin
            @(negedge clk);
            start = 1'b1;
            data  = d;
            @(negedge clk);              // start was sampled at this cycle's rising edge (E0)
            start = 1'b0;
            repeat (CPB / 2) @(negedge clk);   // middle of the start bit
            for (k = 0; k < 8; k = k + 1) begin
                repeat (CPB) @(negedge clk);   // middle of data bit k
                checks = checks + 1;
                if (tx !== d[k]) begin
                    failures = failures + 1;
                    $display("DATA_BIT_MISMATCH byte=%h bit=%0d got=%b expected=%b", d, k, tx, d[k]);
                end
            end
            wait (busy == 1'b0);
            repeat (2) @(negedge clk);
        end
    endtask

    initial begin
        if (!$value$plusargs("NONCE=%s", nonce)) nonce = "none";
        repeat (3) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);
        send_and_check(8'h01);
        send_and_check(8'h80);
        send_and_check(8'h35);
        send_and_check(8'hCA);
        send_and_check(8'h0F);
        if (!done) begin
            done = 1'b1;
            $display("VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks, failures);
            $finish;
        end
    end

    initial begin
        #200000;
        if (!done) begin
            done = 1'b1;
            $display("VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks + 1, failures + 1);
            $finish;
        end
    end
endmodule
=== END FILE ===
