                cycles = cycles + 1;
                @(negedge clk);
            end
            checks = checks + 1;
            if (cycles != 11 * CPB) begin
                failures = failures + 1;
                $display("FRAME_PERIOD_MISMATCH byte=%h busy_cycles=%0d expected=%0d", d, cycles, 11 * CPB);
            end
            repeat (2) @(negedge clk);
        end
    endtask

    initial begin
        get_nonce;
        repeat (3) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);
        send_and_measure(8'h55);
        send_and_measure(8'h00);
        send_and_measure(8'hFF);
        if (!done) begin
            done = 1'b1;
            $display("VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks, failures);
            $finish;
        end
    end

    initial begin
        #200000;
        if (!done) begin
            done = 1'b1;
            $display("VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks + 1, failures + 1);
            $finish;
        end
    end
